assignments.referenceSolution:
Equal and exact splits are straightforward conservation. The percentage split is the classic apportionment problem: floor everything, then give the leftover units to the biggest fractional parts. Using `Fraction` makes both the percent-sum check and the remainders exact, so the result is deterministic across machines.

**`splits.py`**

```python
from collections.abc import Mapping, Sequence
from decimal import Decimal
from fractions import Fraction


def _check_total(total: int) -> None:
    if type(total) is not int or total <= 0:
        raise ValueError("total must be a positive integer")


def split_equal(total: int, users: Sequence[str]) -> dict[str, int]:
    _check_total(total)
    if not users:
        raise ValueError("users must not be empty")
    if len(set(users)) != len(users):
        raise ValueError("users must be unique")
    base, extra = divmod(total, len(users))
    return {user: base + (1 if i < extra else 0) for i, user in enumerate(users)}


def split_exact(total: int, amounts: Mapping[str, int]) -> dict[str, int]:
    _check_total(total)
    if not amounts:
        raise ValueError("amounts must not be empty")
    for user, amount in amounts.items():
        if type(amount) is not int or amount <= 0:
            raise ValueError(f"amount for {user!r} must be a positive integer")
    if sum(amounts.values()) != total:
        raise ValueError(f"amounts sum to {sum(amounts.values())}, expected {total}")
    return dict(amounts)


def split_percentage(
    total: int, percents: Mapping[str, int | str | Decimal | Fraction]
) -> dict[str, int]:
    _check_total(total)
    if not percents:
        raise ValueError("percents must not be empty")
    users = list(percents)
    pcts: list[Fraction] = []
    for user in users:
        raw = percents[user]
        if isinstance(raw, float):
            raise TypeError("percentages must not be floats; use int, str, Decimal or Fraction")
        pct = Fraction(raw)
        if pct <= 0:
            raise ValueError(f"percentage for {user!r} must be positive")
        pcts.append(pct)
    if sum(pcts) != 100:
        raise ValueError("percentages must sum to exactly 100")

    exact = [Fraction(total) * pct / 100 for pct in pcts]
    floors = [share.numerator // share.denominator for share in exact]
    remainders = [share - floor for share, floor in zip(exact, floors)]
    leftover = total - sum(floors)
    order = sorted(range(len(users)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        floors[i] += 1
    return dict(zip(users, floors))
```

**`test_splits.py`**

```python
import random
from decimal import Decimal
from fractions import Fraction

import pytest

from splits import split_equal, split_exact, split_percentage


def test_equal_split_gives_remainder_to_first_users():
    assert split_equal(1000, ["alice", "bob", "carol"]) == {"alice": 334, "bob": 333, "carol": 333}
    assert list(split_equal(2, ["x", "y", "z"]).items()) == [("x", 1), ("y", 1), ("z", 0)]


@pytest.mark.parametrize(
    "total, users",
    [(0, ["a"]), (-5, ["a"]), (10, []), (10, ["a", "a"]), (1.5, ["a"]), (True, ["a"])],
)
def test_equal_split_validation(total, users):
    with pytest.raises(ValueError):
        split_equal(total, users)


def test_exact_split():
    assert split_exact(1000, {"alice": 700, "bob": 300}) == {"alice": 700, "bob": 300}
    with pytest.raises(ValueError):
        split_exact(1000, {"alice": 700, "bob": 200})
    with pytest.raises(ValueError):
        split_exact(1000, {"alice": 1000, "bob": 0})
    with pytest.raises(ValueError):
        split_exact(1000, {"alice": 500.0, "bob": 500})


def test_percentage_split_largest_remainder():
    shares = split_percentage(100, {"a": "33.333", "b": "33.333", "c": "33.334"})
    assert shares == {"a": 33, "b": 33, "c": 34}
    assert split_percentage(10, {"a": Fraction(100, 3), "b": Fraction(200, 3)}) == {"a": 3, "b": 7}
    assert split_percentage(7, {"a": 50, "b": 50}) == {"a": 4, "b": 3}   # tie -> earlier user
    assert split_percentage(1000, {"a": Decimal("12.5"), "b": Decimal("87.5")}) == {"a": 125, "b": 875}


def test_percentage_validation():
    with pytest.raises(TypeError):
        split_percentage(100, {"a": 50.0, "b": 50})
    with pytest.raises(ValueError):
        split_percentage(100, {"a": 60, "b": 30})
    with pytest.raises(ValueError):
        split_percentage(100, {"a": 110, "b": -10})
    with pytest.raises(ValueError):
        split_percentage(100, {})


def test_shares_always_conserve_the_total_and_stay_within_one_unit():
    rng = random.Random(42)
    for _ in range(300):
        n = rng.randint(1, 7)
        cuts = sorted(rng.sample(range(1, 1000), n - 1)) if n > 1 else []
        parts = [b - a for a, b in zip([0] + cuts, cuts + [1000])]
        percents = {f"u{i}": Fraction(p, 10) for i, p in enumerate(parts)}
        total = rng.randint(1, 10_000)
        shares = split_percentage(total, percents)
        assert sum(shares.values()) == total
        for user, pct in percents.items():
            exact = Fraction(total) * pct / 100
            assert abs(shares[user] - exact) < 1
